const e="geopolitica-dell-anima-modello-civilta-organismo",o="geopolitica-dell-anima/modello-civilta-organismo",i="https://precious-cassata-42205a.netlify.app/geopolitica-dell-anima/modello-civilta-organismo",t="Il Modello della Civiltà come Organismo",c="",a="Seleziona una civiltà e scopri la sua diagnosi",r="geopolitica-dell-anima",l="geopolitica-dell-anima",n=[{type:"h",level:1,runs:[{t:"Il Modello della "},{t:"Civiltà come Organismo",i:!0}],role:"p"},{type:"p",role:"p",runs:[{t:"Una metafora biologica per leggere l’ascesa e il declino delle potenze. Ogni civiltà è un organismo vivente: ha un corpo che produce, una mente che pensa, un’anima che ricorda, uno spirito che crede. Quando uno di questi si ammala, l’intero organismo entra in crisi."}]},{type:"p",role:"p",runs:[{t:"Civiltà"}]},{type:"p",role:"p",runs:[{t:"Civiltà = Corpo + Mente + Anima + Spirito"}]},{type:"p",role:"lede",runs:[{t:"Seleziona una civiltà e scopri la sua diagnosi"}]},{type:"p",role:"p",runs:[{t:"Il modello della "},{t:"Civiltà come Organismo",b:!0},{t:" nasce da un’intuizione semplice: le civiltà non muoiono quando perdono denaro. Muoiono quando perdono lo "},{t:"Spirito",b:!0},{t:". La storia lo dimostra: Roma cadde quando il mito si spense, prima che l’esercito si ritirasse. L’Europa oggi possiede ancora corpo e mente, ma l’anima è frammentata e lo spirito è incerto."}]},{type:"p",role:"p",runs:[{t:"Questa mappa a quattro dimensioni permette di diagnosticare la salute di una civiltà (o di una nazione) esattamente come un medico valuta un paziente: osservando i sintomi, misurando le funzioni vitali, identificando le patologie prima che diventano letali."}]},{type:"p",role:"p",runs:[{t:"Lo schema è "},{t:"frattale",b:!0},{t:": la stessa struttura che vale per le civiltà vale per l’uomo. Ciò che la Geopolitica dell’Anima vede nel macrocosmo delle potenze si riflette nel microcosmo della persona. Per questo il modello non è solo uno strumento di analisi geopolitica, ma anche una mappa di crescita personale."}]},{type:"p",role:"p",runs:[{t:"Usa lo strumento interattivo qui sotto: seleziona una civiltà preselezionata per vedere la sua diagnosi completa, oppure usalo come lente per analizzare qualsiasi altra realtà collettiva o individuale."}]},{type:"p",role:"p",runs:[{t:"⚖"}]},{type:"p",role:"p",runs:[{t:"Corpo"}]},{type:"p",role:"p",runs:[{t:"Economia, esercito, tecnologia, territorio"}]},{type:"p",role:"p",runs:[{t:"Economia Esercito Tecnologia Territorio"}]},{type:"p",role:"p",runs:[{t:"⚙"}]},{type:"p",role:"p",runs:[{t:"Mente"}]},{type:"p",role:"p",runs:[{t:"Ideologie, università, media, scuole"}]},{type:"p",role:"p",runs:[{t:"Ideologie Università Media Scuole"}]},{type:"p",role:"p",runs:[{t:"☹"}]},{type:"p",role:"p",runs:[{t:"Anima"}]},{type:"p",role:"p",runs:[{t:"Miti, eroi, memorie, traumi"}]},{type:"p",role:"p",runs:[{t:"Miti Eroi Memorie Traumi"}]},{type:"p",role:"p",runs:[{t:"★"}]},{type:"p",role:"p",runs:[{t:"Spirito"}]},{type:"p",role:"p",runs:[{t:"Per cosa vivere morire?"}]},{type:"p",role:"p",runs:[{t:"Domanda ultima Per cosa vivo Per cosa muoio Trascendenza"}]},{type:"p",role:"label",runs:[{t:"Seleziona una civiltà da analizzare"}]},{type:"p",role:"p",runs:[{t:"Roma Europa USA Cina Russia Iran"}]},{type:"p",role:"p",runs:[{t:"Roma Antica"}]},{type:"p",role:"p",runs:[{t:"Diagnosi completa dell’organismo-civiltà"}]},{type:"p",role:"p",runs:[{t:"Corpo"}]},{type:"p",role:"p",runs:[{t:"Corpo Medio"}]},{type:"p",role:"p",runs:[{t:"Mente"}]},{type:"p",role:"p",runs:[{t:"Mente Medio"}]},{type:"p",role:"p",runs:[{t:"Anima"}]},{type:"p",role:"p",runs:[{t:"Anima Medio"}]},{type:"p",role:"p",runs:[{t:"Spirito"}]},{type:"p",role:"p",runs:[{t:"Spirito Medio"}]},{type:"p",role:"p",runs:[{t:"Diagnosi"}]},{type:"p",role:"p",runs:[{t:"«Le civiltà non muoiono per assassinio. Muoiono per suicidio. Prima perde lo Spirito, poi l’Anima si frammenta, poi la Mente si offusca. Solo alla fine il Corpo crolla. Quando vedi un impero cadere, stai guardando l’ultimo atto di una malattia iniziata molto prima.»"}]},{type:"p",role:"p",runs:[{t:"— Sistema MetaHistoria, Modello Civiltà-Organismo"}]}],p=[],s=["O. Spengler, Il tramonto dell’Occidente (1918)","A. Toynbee, A Study of History (1934-61)","C. Schmitt, Teologia politica (1922)","MetaHistoria, Frontiere — Modello Civiltà-Organismo (2025)"],u={blocks:40,chars:2360,hash:"3a8a917ed655c4149d2db86f2193ce03dfb3532fe3625796fe08a592b043ca96"},m={id:e,slug:o,sourceUrl:i,title:t,kicker:"",lede:a,category:r,parentId:l,blocks:n,prevNext:p,references:s,stats:u};export{n as blocks,r as category,m as default,e as id,c as kicker,a as lede,l as parentId,p as prevNext,s as references,o as slug,i as sourceUrl,u as stats,t as title};
